    ["lesson"] = {
      { "I learned Life Tap, a way to feed my magic from my own health; the hunger would come out of me.", tags = { "spell:Life_Tap" } },
      { "I learned Fear, and could put the terror on the other side of a fight for once.", tags = { "spell:Fear" } },
      { "I learned Drain Life, a hungry spell that could keep me alive at someone else's expense.", tags = { "spell:Drain_Life" } },
      { "I learned Corruption, which worked slowly enough to make a quick death seem generous.", tags = { "spell:Corruption" } },
      { "I learned Health Funnel; keeping a demon alive could now cost me more than the summoning.", tags = { "spell:Health_Funnel" } },
      { "Polymorph could turn a foe into a sheep, which is more of an answer than it sounds.", tags = { "spell:Polymorph" } },
      { "Blink was a step through the air to somewhere safer, and I took to it at once.", tags = { "spell:Blink" } },
      { "Frost Nova held a foe in ice while I put some distance between us.", tags = { "spell:Frost_Nova" } },
      { "I could conjure water out of nothing now, which settled the question of what to drink on the road.", tags = { "spell:Conjure_Water" } },
      { "Power Word: Shield was a ward of light to take the blows meant for me.", tags = { "spell:Power_Word:_Shield" } },
      { "Renew was a healing that kept on working long after the prayer was done.", tags = { "spell:Renew" } },
      { "With Resurrection, I could call the dead back to life, which is not a thing to learn lightly.", tags = { "spell:Resurrection" } },
      { "Psychic Scream was a cry that sent foes fleeing in terror.", tags = { "spell:Psychic_Scream" } },
      { "Lay on Hands was the Light's answer for when everything else had failed.", tags = { "spell:Lay_on_Hands" } },
      { "Divine Protection gave me a moment in which nothing could touch me.", tags = { "spell:Divine_Protection" } },
      { "With Hammer of Justice, the Light could stop a foe in its tracks.", tags = { "spell:Hammer_of_Justice" } },
      { "With Charge, the distance between me and a foe stopped mattering.", tags = { "spell:Charge" } },
      { "Execute was the blow that finishes what the rest of a fight began.", tags = { "spell:Execute" } },
      { "Once I could pick pockets, I looked at every purse I passed a little differently.", tags = { "spell:Pick_Pocket" } },
      { "With Sap, I could put a foe to sleep before it knew I was there.", tags = { "spell:Sap" } },
      { "Vanish was a way out of any fight I did not care to finish.", tags = { "spell:Vanish" } },
      { "Sprint was for the times when leaving quickly was the whole plan.", tags = { "spell:Sprint" } },
      { "With the Aspect of the Cheetah, the roads grew shorter.", tags = { "spell:Aspect_of_the_Cheetah" } },
      { "Feign Death was a lie told with my whole body.", tags = { "spell:Feign_Death" } },
      { "With Hunter's Mark, nothing I had marked could hide from me.", tags = { "spell:Hunter's_Mark" } },
      { "Ghost Wolf let me run in the shape of a wolf, as the spirits do.", tags = { "spell:Ghost_Wolf" } },
      { "With Ancestral Spirit, I could call a fallen friend's spirit back into their body.", tags = { "spell:Ancestral_Spirit" } },
      { "Lightning Shield was a ring of crackling light that struck back at whoever struck me.", tags = { "spell:Lightning_Shield" } },
      { "With Entangling Roots, the ground itself would hold a foe for me.", tags = { "spell:Entangling_Roots" } },
      { "Healing Touch was the old craft of mending a body with the wild's own strength.", tags = { "spell:Healing_Touch" } },
      { "Rebirth could bring a fallen friend back in the middle of a fight.", tags = { "spell:Rebirth" } },
      { "I learned Immolate, and liked the prospect of keeping a foe burning while I stayed out of reach.", tags = { "spell:Immolate" } },
      { "I learned Immolate, a nastier sort of fire than any hearth would welcome.", tags = { "spell:Immolate" } },
      { "I learned Life Tap, and could buy more magic with the health I needed to survive using it.", tags = { "spell:Life_Tap" } },
    },
